1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Quote: base price list, single main item, no modifiers ---
6	  it("quotes a plain sword for a new customer — base 100 G +10 % first insurance +5 G fee = 115 G", () => {
7	    expect(
8	      runScenario({
9	        customer: { yearsWithMHPCO: 0 },
10	        steps: [
11	          {
12	            op: "quote",
13	            items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }],
14	          },
15	        ],
16	      }),
17	    ).toEqual({ results: [{ premium: 115 }] });
18	  });
19	  it.todo("quotes a plain amulet for a new customer — base 60 G +10 % +5 G = 71 G");
20	  it.todo("quotes a plain staff for a new customer — base 80 G +10 % +5 G = 93 G");
21	  it.todo("quotes a plain potion for a new customer — base 40 G +10 % +5 G = 49 G");
22	
23	  // --- Quote: components ---
24	  it.todo("quotes a single rune — base 25 G +10 % +5 G = 33 G");
25	  it.todo("quotes a single moonstone — base 25 G +10 % +5 G = 33 G");
26	  it.todo("quotes two alike components separately — base 50 G +10 % +5 G = 60 G");
27	  it.todo("quotes a building block of 3 alike runes at the special base premium 60 G — +10 % +5 G = 71 G");
28	  it.todo("quotes 4 alike runes as one building block plus one single — base 60+25=85 G +10 % +5 G = 99 G");
29	  it.todo("does not form a building block from 3 unalike components (2 runes + 1 moonstone) — base 75 G +10 % +5 G = 88 G");
30	
31	  // --- Quote: multiple items ---
32	  it.todo("sums base premiums of several main items — sword + potion = 140 G +10 % +5 G = 159 G");
33	  it.todo("quotes an empty item list — 0 G base +10 % +5 G = 5 G");
34	
35	  // --- Quote: risk surcharges ---
36	  it.todo("adds a 50 % risk surcharge for a cursed sword — 150 G +10 % +5 G = 170 G");
37	  it.todo("adds a 30 % risk surcharge for a highly enchanted sword (enchantment 5) — 130 G +10 % +5 G = 148 G");
38	  it.todo("does not add the enchantment surcharge below level 5 (enchantment 4) — 100 G +10 % +5 G = 115 G");
39	  it.todo("combines cursed and high-enchantment surcharges on one item — 100 G × 1.5 × 1.3 = 195 G +10 % +5 G = 220 G");
40	  it.todo("applies surcharges per item, not to the whole quote — cursed sword + plain potion = 190 G +10 % +5 G = 214 G");
41	
42	  // --- Quote: customer modifiers ---
43	  it.todo("grants a 20 % loyalty discount to a customer of 2 years — sword 100 G ×0.8 ×1.1 +5 G = 93 G");
44	  it.todo("grants no loyalty discount below 2 years (1 year) — 100 G ×1.1 +5 G = 115 G");
45	  it.todo("applies a 15 % contract discount to the second quote — sword 100 G ×0.85 +5 G = 90 G");
46	  it.todo("applies the 15 % contract discount to every quote after the first, and the 10 % first-insurance surcharge only to the first");
47	  it.todo("combines loyalty and contract discount on a loyal customer's second quote — 100 G ×0.8 ×0.85 +5 G = 73 G");
48	
49	  // --- Quote: rounding ---
50	  it.todo("rounds the premium up to whole G in MHPCO's favour — amulet at 2 years: 60 ×0.8 ×1.1 = 52.8 → 53 +5 G = 58 G");
51	
52	  // --- Claim: basics ---
53	  it.todo("pays a claim minus the 100 G deductible — 300 G damage on a plain amulet pays 200 G");
54	  it.todo("pays nothing when the damage does not exceed the deductible — 100 G damage pays 0 G");
55	  it.todo("applies the deductible once per damage event, not per damaged item — two 200 G damages in one incident pay 300 G");
56	  it.todo("reports the remaining cap after a claim — amulet policy cap 1200 G, 300 G damage pays 200 G, remainingCap 1000 G");
57	
