60	  it.todo("reimburses damage to an item with enchantment 7 in full — 500 G damage minus 100 G = 400 G");
61	  it.todo("fully reimburses damage to an item of dragon material even at enchantment 8 — 500 G damage minus 100 G = 400 G");
62	
